using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine("=== BUILD RESULT: " + (build.Succeeded ? "SUCCESS" : "FAILED") + " ===\n");

// Collect all errors
var errors = new List<(string project, string code, string file, int line, string message)>();

build.VisitAllChildren<Error>(e =>
{
    var project = "";
    var node = e.Parent;
    while (node != null)
    {
        if (node is Project p) { project = p.Name; break; }
        if (node is Target t && t.Project is Project tp) { project = tp.Name; break; }
        node = node.Parent as BaseNode;
    }
    errors.Add((project, e.Code ?? "", e.File ?? "", e.LineNumber, e.Text ?? ""));
});

// Group by project
var byProject = errors.GroupBy(e => e.project).OrderBy(g => g.Key);

Console.WriteLine($"Total errors: {errors.Count}\n");

foreach (var grp in byProject)
{
    Console.WriteLine($"--- Project: {grp.Key} ---");
    foreach (var e in grp.OrderBy(x => x.file).ThenBy(x => x.line))
    {
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
    }
    Console.WriteLine();
}

// Check for dependency failures (MSB3202, MSB4181, etc.)
var depFailureCodes = new HashSet<string> { "MSB3202", "MSB4181" };
var cascadingProjects = new HashSet<string>();

foreach (var e in errors)
{
    if (depFailureCodes.Contains(e.code))
        cascadingProjects.Add(e.project);
}

// Also check CS errors that reference missing types from other projects
Console.WriteLine("=== ANALYSIS ===");
var rootCauseProjects = byProject
    .Where(g => !cascadingProjects.Contains(g.Key))
    .Select(g => g.Key)
    .ToList();

var cascading = byProject
    .Where(g => cascadingProjects.Contains(g.Key))
    .Select(g => g.Key)
    .ToList();

if (cascading.Any())
{
    Console.WriteLine($"\nCascading failures (dependent project failed): {string.Join(", ", cascading)}");
}
Console.WriteLine($"\nRoot cause projects: {string.Join(", ", rootCauseProjects)}");

// Also print warnings that might be relevant
Console.WriteLine("\n=== WARNINGS ===");
build.VisitAllChildren<Warning>(w =>
{
    if (w.Code != null && (w.Code.StartsWith("NU") || w.Code.StartsWith("MSB")))
    {
        Console.WriteLine($"  [{w.Code}] {w.Text}");
    }
});
